def replace_all_emojis(file_path):
    """Remplacer tous les emojis dans un fichier"""

    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            content = f.read()

        original_content = content

        # Remplacer chaque emoji par son SVG
        for emoji, svg in COMPLETE_SVG_ICONS.items():
            content = content.replace(emoji, svg)

        # Sauvegarder seulement si changé
        if content != original_content:
            with open(file_path, 'w', encoding='utf-8') as f:
                f.write(content)
            return True

        return False

    except Exception as e:
        return False

def main():
    print("="*70)
    print("🔄 REMPLACEMENT COMPLET DE TOUS LES EMOJIS")
    print("="*70)
    print()

    total_files = 0
    updated_files = 0

    # Parcourir tous les fichiers HTML
    for root, dirs, files in os.walk('.'):
        # Ignorer les backups
        if 'backup' in root or '.git' in root or 'node_modules' in root:
            continue

        for file in files:
            if file.endswith('.html'):
                total_files += 1
                file_path = os.path.join(root, file)

                if replace_all_emojis(file_path):
                    updated_files += 1
                    if updated_files <= 50:  # Afficher les 50 premiers
                        print(f"✅ {file_path}")

    print()
    print("="*70)
    print(f"✅ REMPLACEMENT TERMINÉ!")
    print(f"   Fichiers traités: {total_files}")
    print(f"   Fichiers modifiés: {updated_files}")
    print(f"   Emojis remplacés: {len(COMPLETE_SVG_ICONS)} types différents")
    print("="*70)

if __name__ == '__main__':
    main()
